<script setup>
import {ref,onMounted} from 'vue'
import {api,labels,date} from '../api'
import RegistrationProof from './RegistrationProof.vue'
import AdminCharacterEditor from './AdminCharacterEditor.vue'
const data=ref(null),tab=ref('reports'),error=ref(''),selection=ref(null),reason=ref(''),busy=ref(false)
const tabs={reports:'举报与申诉',reviews:'评价审核',cards:'卡片管理',users:'账号管理',disputes:'争议处理',audit:'审计日志'}
async function load(){try{data.value=await api('/admin/overview')}catch(e){error.value=e.message}}
function select(resource,id,action){selection.value={resource,resource_id:id,action};reason.value=''}
async function submit(){busy.value=true;try{await api('/admin/moderate',{method:'POST',data:{...selection.value,reason:reason.value}});selection.value=null;await load()}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(load)
</script>
<template><div class="stack"><p class="hint">管理操作均记录审计。此界面不展示任何用户联系方式或管理凭证。</p><div class="admin-tabs"><button v-for="(name,key) in tabs" class="button small" :class="{primary:tab===key}" @click="tab=key">{{name}}</button></div><p v-if="error" class="error">{{error}}</p><form v-if="selection" class="confirm-box stack" @submit.prevent="submit"><strong>确认 {{selection.action}} · {{selection.resource}} #{{selection.resource_id}}</strong><label>处理依据<textarea v-model="reason" minlength="3" maxlength="500" required placeholder="填写审核理由，写入审计日志"></textarea></label><div class="button-row"><button class="button primary" :disabled="busy">提交处理</button><button type="button" class="button" @click="selection=null">取消</button></div></form><template v-if="data"><p v-if="!data[tab]?.length" class="empty-small">暂无需要处理的记录</p><article v-for="r in data[tab]" class="admin-record"><template v-if="tab==='reports'"><div><b>#{{r.id}} · {{r.resource}} #{{r.resource_id}}</b><span class="tag">{{r.status}}</span></div><p>{{r.reason}}</p><p class="hint">{{r.decision}}</p><div class="button-row" v-if="r.status==='pending'"><button class="button small" @click="select('report',r.id,'resolve')">标记已处理</button><button class="button small" @click="select('report',r.id,'reject')">驳回</button></div></template><template v-if="tab==='reviews'"><b>#{{r.id}} · {{r.tags}}</b><p>{{r.body||'无补充文字'}}</p><span class="tag">{{r.status}}</span><div class="button-row"><button class="button small" @click="select('review',r.id,'approve')">通过</button><button class="button small" @click="select('review',r.id,'hide')">隐藏</button><button class="button small" @click="select('review',r.id,'reject')">拒绝</button></div></template><template v-if="tab==='cards'"><b>{{r.type}} #{{r.id}} · {{r.map_name}} · {{r.game_id}}</b><span class="tag">{{labels[r.status]}}</span><button class="button small" @click="select(r.type,r.id,'hide')">隐藏卡片</button></template><template v-if="tab==='users'"><b>#{{r.id}} · {{r.username}}</b><span class="tag">{{r.is_admin?'管理员':r.status}}</span><AdminCharacterEditor :user-id="r.id"/><RegistrationProof v-if="r.has_registration_proof" :user-id="r.id"/><small v-else class="hint">未留存注册截图（历史账号）</small><button v-if="!r.is_admin" class="button small" @click="select('user',r.id,r.status==='banned'?'unban':'ban')">{{r.status==='banned'?'解除封禁':'封禁账号'}}</button></template><template v-if="tab==='disputes'"><b>撮合 #{{r.id}} · 队伍 #{{r.team_id}}</b><button class="button small" @click="select('match',r.id,'cancel')">取消并释放坑位</button></template><template v-if="tab==='audit'"><b>{{r.action}} · {{r.resource}}</b><p>{{r.detail}}</p><small>{{r.actor}} · {{date(r.created_at)}}</small></template></article></template></div></template>
